'use client';

import { useMemo, useState } from 'react';
import { Focus, Maximize2, Network, Search, X } from 'lucide-react';
import type { EnrichedImpactFinding, ImpactAnalytics } from '@/lib/api-client';

const colors: Record<string, string> = { critical: '#e56f5d', high: '#d98b54', medium: '#e5aa5d', low: '#81bf91', informational: '#7186a8' };
const severityOrder = ['critical', 'high', 'medium', 'low', 'informational'];
const nice = (value: string) => value.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
const seriesTotal = (row: ImpactAnalytics['timeSeries'][number]) => severityOrder.reduce((sum, key) => sum + Number(row[key as keyof typeof row] || 0), 0);

export function SeverityDonut({ items, active, onSelect }: { items: ImpactAnalytics['severity']; active: string; onSelect: (value: string) => void }) {
  const total = items.reduce((sum, item) => sum + item.count, 0);
  let cursor = 0;
  const gradient = items.map((item) => { const start = cursor; cursor += total ? item.count / total * 100 : 0; return `${colors[item.name]} ${start}% ${cursor}%`; }).join(',');
  return <ChartFrame title="Impact severity distribution" subtitle="Finding volume and share by recorded severity."><div className="impact-donut-layout"><button className="impact-donut" style={{ background: total ? `conic-gradient(${gradient})` : '#252525' }} onClick={() => onSelect('all')} aria-label={`All severities, ${total} findings`}><span><b>{total}</b>findings</span></button><div className="impact-legend">{items.map((item) => <button key={item.name} className={active === item.name ? 'active' : ''} onClick={() => onSelect(active === item.name ? 'all' : item.name)}><i style={{ background: colors[item.name] }}/><span>{nice(item.name)}<small>{total ? Math.round(item.count / total * 100) : 0}%</small></span><b>{item.count}</b></button>)}</div></div></ChartFrame>;
}

export function ImpactOverTime({ rows }: { rows: ImpactAnalytics['timeSeries'] }) {
  const max = Math.max(1, ...rows.map(seriesTotal));
  return <ChartFrame title="Impact over time" subtitle="Detected findings grouped by severity and day.">{rows.length ? <div className="impact-time-chart" role="img" aria-label="Stacked impact findings over time">{rows.map((row) => <div className="impact-time-column" key={row.date}><div className="impact-stack" style={{ height: `${Math.max(8, seriesTotal(row) / max * 170)}px` }}>{severityOrder.map((key) => { const value = Number(row[key as keyof typeof row] || 0); return value ? <i key={key} style={{ flex: value, background: colors[key] }} title={`${nice(key)}: ${value}`} /> : null; })}</div><span>{new Date(`${row.date}T00:00:00`).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</span></div>)}</div> : <EmptyChart text="No impact findings have detection timestamps in this range." />}</ChartFrame>;
}

export function DirectTransitiveChart({ findings, onSelect }: { findings: EnrichedImpactFinding[]; onSelect: (apiId: string) => void }) {
  const groups = useMemo(() => [...new Set(findings.map((item) => item.changedApiId))].map((apiId) => ({ apiId, name: findings.find((item) => item.changedApiId === apiId)?.changedApiName || 'Unknown', direct: findings.filter((item) => item.changedApiId === apiId && item.impact === 'direct').length, transitive: findings.filter((item) => item.changedApiId === apiId && item.impact === 'transitive').length })).sort((a, b) => b.direct + b.transitive - a.direct - a.transitive), [findings]);
  const max = Math.max(1, ...groups.map((item) => item.direct + item.transitive));
  return <ChartFrame title="Direct vs transitive impact" subtitle="Which API changes generate the broadest downstream exposure.">{groups.length ? <div className="impact-group-bars">{groups.map((item) => <button key={item.apiId} onClick={() => onSelect(item.apiId)}><span>{item.name}</span><div><i className="direct" style={{ width: `${item.direct / max * 100}%` }} title={`Direct: ${item.direct}`}/><i className="transitive" style={{ width: `${item.transitive / max * 100}%` }} title={`Transitive: ${item.transitive}`}/></div><b>{item.direct + item.transitive}</b></button>)}</div> : <EmptyChart text="No direct or transitive findings are recorded." />}</ChartFrame>;
}

export function PropagationDepth({ rows }: { rows: ImpactAnalytics['depth'] }) {
  const max = Math.max(1, ...rows.map((item) => Math.max(item.uniqueApis, item.paths)));
  return <ChartFrame title="Impact propagation depth" subtitle="Unique APIs reached versus total persisted impact paths."><div className="impact-depth">{rows.map((row) => <div key={row.depth}><span>{row.label}</span><div><i className="apis" style={{ width: `${row.uniqueApis / max * 100}%` }}/><i className="paths" style={{ width: `${row.paths / max * 100}%` }}/></div><small>{row.uniqueApis} APIs / {row.paths} paths</small></div>)}</div></ChartFrame>;
}

export function RiskBubbleChart({ rows, onSelect }: { rows: ImpactAnalytics['apiRisk']; onSelect: (apiId: string) => void }) {
  const maxX = Math.max(1, ...rows.map((item) => item.upstreamApis)); const maxY = Math.max(1, ...rows.map((item) => item.findings)); const maxSize = Math.max(1, ...rows.map((item) => item.affectedEndpoints));
  return <ChartFrame title="Most affected APIs" subtitle="Upstream exposure, finding volume, affected endpoints, and peak severity.">{rows.length ? <div className="impact-bubble-plot"><span className="axis-y">Impact findings</span><span className="axis-x">Upstream APIs affected</span>{rows.map((item) => { const size = 34 + item.affectedEndpoints / maxSize * 34; return <button key={item.apiId} onClick={() => onSelect(item.apiId)} style={{ left: `${8 + item.upstreamApis / maxX * 82}%`, bottom: `${10 + item.findings / maxY * 74}%`, width: size, height: size, background: `${colors[item.highestSeverity]}33`, borderColor: colors[item.highestSeverity] }} title={`${item.name}: ${item.findings} findings, ${item.upstreamApis} upstream APIs, ${item.affectedEndpoints} affected endpoints`}><span>{item.name.slice(0, 3).toUpperCase()}</span></button>; })}</div> : <EmptyChart text="No affected APIs are available for bubble analysis." />}</ChartFrame>;
}

export function RiskTreemap({ rows, onSelect }: { rows: ImpactAnalytics['apiRisk']; onSelect: (apiId: string) => void }) {
  const total = rows.reduce((sum, item) => sum + item.findings, 0);
  return <ChartFrame title="API risk concentration" subtitle="Rectangle area represents finding concentration; color represents peak severity.">{rows.length ? <div className="impact-treemap">{rows.map((item) => <button key={item.apiId} onClick={() => onSelect(item.apiId)} style={{ flexGrow: Math.max(1, item.findings), flexBasis: `${Math.max(24, total ? item.findings / total * 100 : 25)}%`, borderColor: colors[item.highestSeverity], background: `${colors[item.highestSeverity]}18` }}><b>{item.name}</b><span>{item.findings} findings</span><small>{nice(item.highestSeverity)}</small></button>)}</div> : <EmptyChart text="No API risk concentration can be calculated yet." />}</ChartFrame>;
}

export function CategorySeverity({ rows, activeSeverity, onSeverity }: { rows: ImpactAnalytics['categorySeverity']; activeSeverity: string; onSeverity: (value: string) => void }) {
  const max = Math.max(1, ...rows.map((row) => severityOrder.reduce((sum, key) => sum + (row.values[key] || 0), 0)));
  return <ChartFrame title="Change category vs impact severity" subtitle="Which contract changes produce the most severe downstream findings.">{rows.length ? <div className="impact-category-chart">{rows.map((row) => <div key={row.category}><span>{nice(row.category)}</span><div>{severityOrder.map((key) => row.values[key] ? <button key={key} className={activeSeverity === key ? 'active' : ''} style={{ width: `${row.values[key] / max * 100}%`, background: colors[key] }} onClick={() => onSeverity(key)} title={`${nice(key)}: ${row.values[key]}`} /> : null)}</div><b>{severityOrder.reduce((sum, key) => sum + (row.values[key] || 0), 0)}</b></div>)}</div> : <EmptyChart text="No categorized impact findings are recorded." />}</ChartFrame>;
}

export function RiskMatrix({ cells, onSelect }: { cells: ImpactAnalytics['matrix']; onSelect: (apiId: string) => void }) {
  const upstream = [...new Map(cells.map((cell) => [cell.upstreamApiId, cell.upstreamApiName])).entries()]; const dependent = [...new Map(cells.map((cell) => [cell.dependentApiId, cell.dependentApiName])).entries()];
  return <ChartFrame wide title="Dependency risk matrix" subtitle="Valid upstream-to-dependent relationships with persisted findings only.">{cells.length ? <div className="impact-matrix-wrap"><div className="impact-matrix" style={{ gridTemplateColumns: `150px repeat(${dependent.length}, minmax(72px, 1fr))` }}><span/><>{dependent.map(([id, name]) => <b key={id} title={name}>{name}</b>)}</>{upstream.map(([upstreamId, upstreamName]) => <div className="impact-matrix-row" key={upstreamId} style={{ gridColumn: `1 / span ${dependent.length + 1}`, gridTemplateColumns: `150px repeat(${dependent.length}, minmax(72px, 1fr))` }}><strong>{upstreamName}</strong>{dependent.map(([dependentId]) => { const cell = cells.find((item) => item.upstreamApiId === upstreamId && item.dependentApiId === dependentId); return cell ? <button key={dependentId} style={{ background: `${colors[cell.highestSeverity]}2b`, borderColor: colors[cell.highestSeverity] }} onClick={() => onSelect(dependentId)} title={`${cell.upstreamApiName} to ${cell.dependentApiName}: ${cell.count} findings, ${nice(cell.highestSeverity)}`}>{cell.count}</button> : <span className="empty-cell" key={dependentId}>-</span>; })}</div>)}</div></div> : <EmptyChart text="No valid dependency relationship has an impact finding." />}</ChartFrame>;
}

export function ResolutionTimeline({ findings, history }: { findings: EnrichedImpactFinding[]; history: ImpactAnalytics['statusHistory'] }) {
  const events = [...findings.map((item) => ({ id: `detected-${item.id}`, findingId: item.id, status: 'detected', at: item.detectedAt, text: `${item.changedApiName} to ${item.dependentApiName}` })), ...history.map((item) => ({ id: item.id, findingId: item.findingId, status: item.toStatus, at: item.occurredAt, text: item.note || nice(item.toStatus) }))].sort((a, b) => new Date(b.at).getTime() - new Date(a.at).getTime());
  return <ChartFrame wide title="Impact resolution timeline" subtitle="Persisted detection and status-transition events; unresolved findings retain their age.">{events.length ? <div className="impact-resolution-timeline">{events.map((event) => <div key={event.id}><i/><time>{new Date(event.at).toLocaleString()}</time><b>{nice(event.status)}</b><span>{event.text}</span></div>)}</div> : <EmptyChart text="No impact lifecycle events have been recorded." />}</ChartFrame>;
}

export function ImpactPropagationGraph({ data, findings, onSelectApi }: { data: ImpactAnalytics; findings: EnrichedImpactFinding[]; onSelectApi: (id: string) => void }) {
  const [selected, setSelected] = useState<string | null>(null); const [edge, setEdge] = useState<string | null>(null); const [search, setSearch] = useState(''); const [focus, setFocus] = useState(false); const [zoom, setZoom] = useState(1);
  const nodeIds = new Set(findings.flatMap((item) => [item.changedApiId, item.dependentApiId]));
  const nodes = data.apis.filter((api) => nodeIds.has(api.id) && api.name.toLowerCase().includes(search.toLowerCase()));
  const ids = new Set(nodes.map((node) => node.id)); const edges = findings.filter((item) => ids.has(item.changedApiId) && ids.has(item.dependentApiId));
  const focusedIds = selected && focus ? new Set([selected, ...edges.filter((item) => item.changedApiId === selected || item.dependentApiId === selected).flatMap((item) => [item.changedApiId, item.dependentApiId])]) : ids;
  const positions = new Map(nodes.map((node, index) => { const roots = new Set(edges.map((item) => item.changedApiId)); const root = roots.has(node.id); const peers = nodes.filter((candidate) => roots.has(candidate.id) === root); return [node.id, { x: root ? 220 : 540 + (index % 2) * 300, y: 90 + (peers.indexOf(node) + 1) * 520 / (peers.length + 1) }]; }));
  const selectedFinding = findings.find((item) => item.id === edge); const selectedApi = data.apis.find((api) => api.id === selected);
  return <ChartFrame wide title="Dependency impact propagation" subtitle="Changed APIs, demonstrated direct exposure, and potential downstream propagation."><div className="impact-graph-toolbar"><label><Search size={14}/><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search impacted APIs" aria-label="Search impacted APIs"/>{search && <button onClick={() => setSearch('')} aria-label="Clear API search"><X size={13}/></button>}</label><button className={focus ? 'active' : ''} onClick={() => setFocus(!focus)}><Focus size={14}/>Focus</button><button onClick={() => setZoom(1)}><Maximize2 size={14}/>Fit</button></div>{nodes.length ? <div className="impact-graph-shell"><div className="impact-graph-canvas" onWheel={(event) => { event.preventDefault(); setZoom((value) => Math.max(.75, Math.min(1.35, value + (event.deltaY < 0 ? .08 : -.08)))); }}><svg viewBox="0 0 1000 700" style={{ transform: `scale(${zoom})` }} aria-label="Impact propagation graph"><defs><marker id="impact-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#ff6b2c"/></marker></defs>{edges.map((item, index) => { const from = positions.get(item.changedApiId); const to = positions.get(item.dependentApiId); if (!from || !to) return null; const dim = !focusedIds.has(item.changedApiId) || !focusedIds.has(item.dependentApiId); return <g className={dim ? 'dimmed' : ''} key={item.id} onClick={() => setEdge(item.id)}><path d={`M${from.x + 72},${from.y} C${from.x + 210},${from.y + index % 3 * 18} ${to.x - 210},${to.y - index % 3 * 18} ${to.x - 72},${to.y}`} stroke={colors[item.severity]} markerEnd="url(#impact-arrow)"/><text x={(from.x + to.x) / 2} y={(from.y + to.y) / 2 - 7}>{item.relationship || item.impact}</text></g>; })}{nodes.map((node) => { const point = positions.get(node.id)!; const root = findings.some((item) => item.changedApiId === node.id); const direct = findings.some((item) => item.dependentApiId === node.id && item.impact === 'direct'); return <g key={node.id} className={`${!focusedIds.has(node.id) ? 'dimmed' : ''} ${selected === node.id ? 'selected' : ''}`} transform={`translate(${point.x - 72},${point.y - 30})`} onClick={() => { setSelected(node.id); setEdge(null); onSelectApi(node.id); }}><rect width="144" height="60" rx="6" className={root ? 'root' : direct ? 'direct' : 'transitive'}/><text className="name" x="12" y="25">{node.name.length > 18 ? `${node.name.slice(0, 17)}...` : node.name}</text><text x="12" y="44">{root ? 'Changed API' : direct ? 'Direct impact' : 'Potential transitive'}</text></g>; })}</svg></div><aside>{selectedFinding ? <><p className="page-kicker">Dependency evidence</p><h4>{selectedFinding.changedApiName} to {selectedFinding.dependentApiName}</h4><p>{selectedFinding.evidence}</p><small>{nice(selectedFinding.confidence)} / {nice(selectedFinding.severity)}</small></> : selectedApi ? <><p className="page-kicker">Impacted API</p><h4>{selectedApi.name}</h4><p>{selectedApi.description || 'No description recorded.'}</p><small>{findings.filter((item) => item.dependentApiId === selectedApi.id).length} findings</small></> : <><Network size={20}/><h4>Select a node or edge</h4><p>Inspect the recorded impact and dependency evidence.</p></>}</aside></div> : <EmptyChart text="No persisted impact paths are available." />}</ChartFrame>;
}

function ChartFrame({ title, subtitle, children, wide = false }: { title: string; subtitle: string; children: React.ReactNode; wide?: boolean }) { return <section className={`impact-chart-card ${wide ? 'wide' : ''}`}><header><div><h3>{title}</h3><p>{subtitle}</p></div></header><div className="impact-chart-body">{children}</div></section>; }
function EmptyChart({ text }: { text: string }) { return <div className="impact-empty"><span>NO DATA</span><p>{text}</p></div>; }
