'use client';

import { ChangeEvent, useState } from 'react';
import { Check, FileUp, LoaderCircle, Upload } from 'lucide-react';
import { apiClient } from '@/lib/api-client';

export function SpecificationImport({ projectId }: { projectId: string }) {
  const [filename, setFilename] = useState(''); const [content, setContent] = useState(''); const [preview, setPreview] = useState<Awaited<ReturnType<typeof apiClient.imports.preview>>['data']>(); const [selected, setSelected] = useState<number[]>([]); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  async function readFile(event: ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; if (!file) return; setFilename(file.name); setContent(await file.text()); setPreview(undefined); setMessage(''); setError(''); }
  async function previewSpec() { if (!filename || !content) return; setBusy(true); setError(''); const result = await apiClient.imports.preview(projectId, { filename, content }); setBusy(false); if (!result.success || !result.data) { setError(result.error?.message || 'Could not parse this specification.'); return; } setPreview(result.data); setSelected(result.data.specification.operations.map((_, index) => index)); }
  async function register() { if (!preview) return; setBusy(true); setError(''); const result = await apiClient.imports.register(projectId, { importId: preview.import.id, selectedOperations: selected }); setBusy(false); if (!result.success) { setError(result.error?.message || 'Could not register the selected operations.'); return; } setMessage(`${result.data?.registeredOperations || selected.length} operations registered successfully.`); }
  return <div className="import-flow"><div className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">Specification ingestion</p><h3>Import an API specification</h3><p>Supported: OpenAPI 3.0/3.1, Swagger 2.0, and WSDL 1.1/2.0.</p></div><FileUp size={18}/></div><label className="file-drop"><input type="file" accept=".json,.yaml,.yml,.xml" onChange={readFile}/><Upload size={20}/><b>{filename || 'Choose a specification file'}</b><small>Maximum 5 MB · external references are reported, never fetched</small></label>{filename && <div className="import-actions"><button className="app-button" disabled={busy} onClick={() => void previewSpec()}>{busy ? <LoaderCircle className="spin" size={15}/> : <FileUp size={15}/>} Preview specification</button><button className="button button-quiet" onClick={() => { setFilename(''); setContent(''); setPreview(undefined); }}>Clear</button></div>}{error && <div className="data-alert" role="alert">{error}</div>}{message && <div className="data-success" role="status">{message}</div>}</div>{preview && <div className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">Preview</p><h3>{preview.specification.title}</h3><p>{preview.specification.format} · version {preview.specification.apiVersion} · {preview.specification.operations.length} operations</p></div><button className="app-button" disabled={busy || !selected.length} onClick={() => void register()}><Check size={15}/> Register selected ({selected.length})</button></div><div className="import-operations">{preview.specification.operations.map((operation, index) => <label className={`import-operation ${selected.includes(index) ? 'selected' : ''}`} key={`${operation.method}-${operation.path}-${index}`}><input type="checkbox" checked={selected.includes(index)} onChange={() => setSelected((current) => current.includes(index) ? current.filter((item) => item !== index) : [...current, index])}/><span className={`method method-${operation.method.toLowerCase()}`}>{operation.method}</span><span><b>{operation.name}</b><small>{operation.path}{operation.description ? ` · ${operation.description}` : ''}</small></span><em>{operation.validationStatus}</em></label>)}</div></div>}</div>;
}
