'use client';

import { useEffect, useMemo, useState } from 'react';
import { AlertTriangle, CheckCircle2, GitBranch, Search, ShieldAlert } from 'lucide-react';
import { apiClient, type ImpactAnalytics } from '@/lib/api-client';
import { ImpactPropagationGraph } from '@/components/impact-visualizations';

export function BreakingDependencies({ projectId }: { projectId: string }) {
  const [data, setData] = useState<ImpactAnalytics | null>(null);
  const [selected, setSelected] = useState<string | null>(null);
  const [severity, setSeverity] = useState('all');
  const [status, setStatus] = useState('all');
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  useEffect(() => { void apiClient.changes.analytics(projectId).then((result) => { if (result.success && result.data) setData(result.data); else setError(result.error?.message || 'Could not load breaking dependency findings.'); setLoading(false); }); }, [projectId]);
  const findings = useMemo(() => (data?.findings || []).filter((finding) => (severity === 'all' || finding.severity === severity) && (status === 'all' || finding.status === status) && (!query || `${finding.changedApiName} ${finding.dependentApiName} ${finding.changeType}`.toLowerCase().includes(query.toLowerCase()))), [data, severity, status, query]);
  if (loading) return <div className="data-state" role="status">Loading breaking dependency findings...</div>;
  if (error) return <div className="data-alert" role="alert">{error}</div>;
  if (!data) return null;
  const critical = findings.filter((finding) => finding.severity === 'critical' || finding.severity === 'high').length;
  const confirmed = findings.filter((finding) => finding.confidence === 'confirmed_evidence' || finding.confidence === 'strong_evidence').length;
  return <div className="workspace-page breaking-workspace"><div className="impact-heading"><div><p className="page-kicker">Analysis / breaking dependencies</p><h2>Breaking dependency explorer</h2><p>Investigate which consumers may be exposed to recorded contract changes and why.</p></div><GitBranch size={22}/></div><div className="impact-filterbar"><label className="breaking-search"><Search size={14}/><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search changed or dependent APIs" aria-label="Search findings"/></label><label>Severity<select value={severity} onChange={(event) => setSeverity(event.target.value)}><option value="all">All severities</option><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></label><label>Review state<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">All states</option><option value="open">Open</option><option value="under_review">Under review</option><option value="acknowledged">Acknowledged</option><option value="resolved">Resolved</option><option value="accepted_risk">Accepted risk</option></select></label></div><div className="impact-summary-grid breaking-summary"><article><AlertTriangle/><b>{findings.length}</b><small>Visible findings</small></article><article><ShieldAlert/><b>{critical}</b><small>Critical / high risk</small></article><article><CheckCircle2/><b>{confirmed}</b><small>Strong evidence</small></article><article><GitBranch/><b>{new Set(findings.map((finding) => finding.dependentApiId)).size}</b><small>Affected consumers</small></article></div><section className="workspace-section breaking-findings-panel"><div className="section-title-row"><div><p className="page-kicker">Review queue</p><h3>Dependency findings</h3></div><span>{findings.length} records</span></div>{findings.length ? <div className="breaking-findings-list">{findings.map((finding) => <button key={finding.id} className={selected === finding.id ? 'selected' : ''} onClick={() => setSelected(selected === finding.id ? null : finding.id)}><span className={`breaking-severity ${finding.severity}`}/><span><b>{finding.changedApiName} <em>to</em> {finding.dependentApiName}</b><small>{finding.changeType.replaceAll('_', ' ')} - {finding.contractPath || 'contract path unavailable'}</small></span><strong>{finding.impact}</strong><i>{finding.status.replaceAll('_', ' ')}</i></button>)}</div> : <div className="empty-state"><AlertTriangle size={22}/><b>No findings match these filters</b><p>Run analysis on a persisted contract change or reset the filters.</p></div>}{selected && <FindingDetail finding={findings.find((finding) => finding.id === selected)}/>}</section><ImpactPropagationGraph data={data} findings={findings} onSelectApi={(apiId) => setQuery(data.apis.find((api) => api.id === apiId)?.name || '')}/></div>;
}

function FindingDetail({ finding }: { finding: ImpactAnalytics['findings'][number] | undefined }) { if (!finding) return null; return <aside className="breaking-detail"><p className="page-kicker">Finding detail</p><h3>{finding.changedApiName} to {finding.dependentApiName}</h3><dl><dt>Impact</dt><dd>{finding.impact}</dd><dt>Severity</dt><dd>{finding.severity}</dd><dt>Confidence</dt><dd>{finding.confidence.replaceAll('_', ' ')}</dd><dt>Relationship</dt><dd>{finding.relationship || 'API-level dependency'}</dd><dt>Version transition</dt><dd>{finding.sourceVersion || 'Unknown'} to {finding.targetVersion || 'Unknown'}</dd></dl><h4>Evidence</h4><p>{finding.evidence}</p><h4>Explanation</h4><p>{finding.explanation}</p></aside>; }
