'use client';

import { FormEvent, useEffect, useState } from 'react';
import { Link2, Plus, Trash2 } from 'lucide-react';
import { apiClient, type ApiRecord, type ApiVersion, type Dependency } from '@/lib/api-client';

export function DependencyRegistry({ projectId }: { projectId: string }) {
  const [dependencies, setDependencies] = useState<Dependency[]>([]); const [apis, setApis] = useState<ApiRecord[]>([]); const [versions, setVersions] = useState<ApiVersion[]>([]); const [source, setSource] = useState(''); const [target, setTarget] = useState(''); const [relationship, setRelationship] = useState('calls'); const [type, setType] = useState<'internal' | 'external'>('internal'); const [evidence, setEvidence] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false);
  async function load() { const apiResult = await apiClient.registry.list(projectId); const dependencyResult = await apiClient.dependencies.list(projectId); if (apiResult.success && apiResult.data) { setApis(apiResult.data); const versionResults = await Promise.all(apiResult.data.map((api) => apiClient.registry.versions(projectId, api.id))); setVersions(versionResults.flatMap((result) => result.data || [])); } if (dependencyResult.success && dependencyResult.data) setDependencies(dependencyResult.data); else setError(dependencyResult.error?.message || 'Could not load dependencies.'); setLoading(false); }
  useEffect(() => { void load(); }, [projectId]);
  async function create(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(''); const result = await apiClient.dependencies.create(projectId, { sourceApiVersionId: source, targetApiVersionId: target, dependencyType: type, relationship, evidence: evidence || undefined }); setBusy(false); if (!result.success) { setError(result.error?.message || 'Could not create dependency.'); return; } setSource(''); setTarget(''); setEvidence(''); await load(); }
  async function remove(id: string) { const result = await apiClient.dependencies.remove(projectId, id); if (!result.success) { setError(result.error?.message || 'Could not remove dependency.'); return; } setDependencies((current) => current.filter((item) => item.dependency.id !== id)); }
  if (loading) return <div className="data-state">Loading dependencies…</div>;
  return <div className="workspace-page"><div className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">Dependency intelligence</p><h3>Dependency registry</h3><p>Relationships are scoped to this project and validated by the backend.</p></div><Link2 size={18}/></div>{error && <div className="data-alert" role="alert">{error}</div>}{dependencies.length ? <div className="dependency-list">{dependencies.map((item) => <article key={item.dependency.id}><Link2 size={15}/><div><b>{item.sourceApi.name} {item.sourceVersion.version}</b><small>{item.dependency.relationship} {item.dependency.targetApiId || item.dependency.targetApiVersionId ? '→ target API' : ''}</small></div><span>{item.dependency.reviewStatus}</span><button aria-label="Remove dependency" onClick={() => void remove(item.dependency.id)}><Trash2 size={15}/></button></article>)}</div> : <div className="empty-state"><Link2 size={22}/><b>No dependencies registered</b><p>Add an explicit relationship between API versions.</p></div>}<form className="dependency-form" onSubmit={create} noValidate><label>Source version<select value={source} onChange={(event) => setSource(event.target.value)} required><option value="">Select source</option>{versions.map((version) => <option key={version.id} value={version.id}>{apis.find((api) => api.id === version.apiId)?.name} · {version.version}</option>)}</select></label><label>Target version<select value={target} onChange={(event) => setTarget(event.target.value)} required><option value="">Select target</option>{versions.filter((version) => version.id !== source).map((version) => <option key={version.id} value={version.id}>{apis.find((api) => api.id === version.apiId)?.name} · {version.version}</option>)}</select></label><label>Relationship<select value={relationship} onChange={(event) => setRelationship(event.target.value)}><option>calls</option><option>consumes</option><option>produces</option><option>requires</option><option>references</option></select></label><label>Type<select value={type} onChange={(event) => setType(event.target.value as 'internal' | 'external')}><option value="internal">Internal</option><option value="external">External</option></select></label><label className="dependency-wide">Evidence<input value={evidence} onChange={(event) => setEvidence(event.target.value)} placeholder="Reason or specification reference"/></label><button disabled={busy || !source || !target}><Plus size={15}/> Add dependency</button></form></div></div>;
}
